"""Functional analysis-of-variance degree-ladder scan.

For a target tabulated on a k-fold product grid (Z_N)^k, the exact best achievable
coefficient of determination of an encoding that uses functions of at most d of
the k coordinates equals the fraction of the variance carried by the components of
order at most d in the orthogonal analysis-of-variance expansion

    f = sum over subsets S of coordinates of  f_S ,

where f_S is obtained by averaging out the complement of S and subtracting the
components of all proper subsets of S. The expansion is orthogonal, so variances
add and the ladder is exact and monotone in d.

Complexity: the components for all 2^k subsets are computed in O(2^k * N^k) time
with O(2^k * N^k) memory; for the zero-sum targets of interest the ladder is
exactly 0 for every d < k and exactly 1 at d = k.
"""

from __future__ import annotations

import itertools
from typing import Dict, List, Sequence, Tuple


def _index(coords: Sequence[int], N: int) -> int:
    idx = 0
    for c in coords:
        idx = idx * N + c
    return idx


def anova_components(values: Sequence[float], N: int, k: int) -> Dict[Tuple[int, ...], List[float]]:
    """Orthogonal analysis-of-variance components indexed by coordinate subsets."""
    size = N ** k
    all_coords = list(itertools.product(range(N), repeat=k))
    comps: Dict[Tuple[int, ...], List[float]] = {}
    for size_s in range(k + 1):
        for S in itertools.combinations(range(k), size_s):
            comp = [0.0] * size
            complement = [j for j in range(k) if j not in S]
            denom = N ** len(complement)
            for c in all_coords:
                acc = 0.0
                for assign in itertools.product(range(N), repeat=len(complement)):
                    cc = list(c)
                    for j, val in zip(complement, assign):
                        cc[j] = val
                    acc += values[_index(cc, N)]
                comp[_index(c, N)] = acc / denom
            for size_t in range(size_s):
                for T in itertools.combinations(S, size_t):
                    sub = comps[T]
                    for i in range(size):
                        comp[i] -= sub[i]
            comps[S] = comp
    return comps


def _variance(v: Sequence[float]) -> float:
    n = len(v)
    mean = sum(v) / n
    return sum((x - mean) ** 2 for x in v) / n


def degree_ladder(values: Sequence[float], N: int, k: int) -> List[float]:
    """Exact best achievable R^2 for encodings of degree d = 0, 1, ..., k."""
    comps = anova_components(values, N, k)
    total = _variance(values)
    ladder: List[float] = []
    for d in range(k + 1):
        proj = [0.0] * (N ** k)
        for S, comp in comps.items():
            if len(S) <= d:
                for i, x in enumerate(comp):
                    proj[i] += x
        ladder.append(0.0 if total <= 0.0 else _variance(proj) / total)
    return ladder


def zero_sum_target(N: int, k: int) -> List[float]:
    """Indicator of the zero-sum hyperplane on (Z_N)^k."""
    return [
        1.0 if sum(c) % N == 0 else 0.0
        for c in itertools.product(range(N), repeat=k)
    ]


if __name__ == "__main__":
    for k in (2, 3):
        vals = zero_sum_target(5, k)
        ladder = degree_ladder(vals, 5, k)
        pretty = ", ".join(f"d={d}: {max(v, 0.0):.6f}" for d, v in enumerate(ladder))
        print(f"k = {k} on (Z_5)^{k}:  {pretty}")
